CREATE TABLE combination_config_bindings (
  binding_id      TEXT NOT NULL,   -- device_id + combination_id 联合标识
  config_id   TEXT NOT NULL,
  PRIMARY KEY (binding_id, config_id),
  FOREIGN KEY (config_id) REFERENCES config(id) ON DELETE CASCADE
);

