/**
 * 互锁校验函数
 * @param {number[]} arr 输入的0/1数组
 * @returns { {ok: boolean, activeGroups: number[], msg: string} }
 */
function checkInterlock(arr,unitId) {
  // 收集触发的组
  const activeGroups = [];
  let groups = []
  if(unitId === 1) {
    groups = DC
    }
    if(unitId === 2) {
    groups = AC
    }
  groups.forEach((indexList, groupNo) => {
    // 本组任意一个下标值等于1 → 本组触发
    const isTrigger = indexList.some(idx => arr[idx] === 1);
    if (isTrigger) {
      activeGroups.push(groupNo + 1); // 组号 1/2/3
    }
  });

  const ok = activeGroups.length <= 1;
  let msginfo = ok ? "校验通过" : `互锁冲突！同时触发组：${activeGroups.join(',')}`;
  return { ok, activeGroups, msginfo };
}


